import java.util.*;

public class Main {

    public static long[] solve(int n, String s) {
        // leftZero[i] 表示位置 i 左侧 0 的个数
        long[] leftZero = new long[n];
        long cnt0 = 0;
        for (int i = 0; i < n; i++) {
            leftZero[i] = cnt0;
            if (s.charAt(i) == '0') {
                cnt0++;
            }
        }

        // rightOne[i] 表示位置 i 右侧 1 的个数
        long[] rightOne = new long[n];
        long cnt1 = 0;
        for (int i = n - 1; i >= 0; i--) {
            rightOne[i] = cnt1;
            if (s.charAt(i) == '1') {
                cnt1++;
            }
        }

        // 计算原串中 01 子序列总数
        long total = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                total += rightOne[i];
            }
        }

        // 计算每个位置反置后的答案
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                // 0 -> 1
                res[i] = total - rightOne[i] + leftZero[i];
            } else {
                // 1 -> 0
                res[i] = total - leftZero[i] + rightOne[i];
            }
        }

        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        long[] ans = solve(n, s);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb.toString());
    }
}
